import{state,setState}from"./state.js";import{renderAll}from"./ui.js";import{showToast,showConfirm}from"./utils.js";import{scheduleSave,getActingChildId,updateBalanceLocally}from"./action-helpers.js";export function deleteHistoryItem(t){showConfirm("Удаление записи","Удалить эту запись из истории?",{onConfirm:()=>{const e=state.history.find(e=>e.id==t);if(e){const t="earn"===e.type?-(e.amount||0):e.amount||0;updateBalanceLocally(e.childId||getActingChildId(),t)}state.history=state.history.filter(e=>e.id!=t),scheduleSave(),renderAll(),showToast("Запись удалена","info")}})}